challenge.solution:
def run(commands):
    state = {"hp": 10, "gold": 0}
    for command in commands:
        parts = command.split()
        if parts[0] == "dig" and len(parts) == 2:
            state["gold"] += int(parts[1])
        elif parts[0] == "fight" and len(parts) == 2:
            state["hp"] -= int(parts[1])
        elif parts[0] == "potion":
            state["hp"] = min(10, state["hp"] + 5)
        if state["hp"] <= 0:
            break
    return state

print(run(["dig 5", "fight 3", "potion"]))

