project_task.solution:
rooms = {
    "camp": {"exits": {"north": "forest"}, "item": None},
    "forest": {"exits": {"south": "camp", "east": "cave", "north": "treasure"}, "item": "map"},
    "cave": {"exits": {"west": "forest"}, "item": "key"},
    "treasure": {"exits": {}, "item": None},
}

def play(commands):
    place = "camp"
    bag = set()
    for command in commands:
        parts = command.split()
        if parts[0] == "go" and len(parts) == 2:
            exits = rooms[place]["exits"]
            if parts[1] not in exits:
                print("You can't go there!")
                continue
            target = exits[parts[1]]
            if target == "treasure":
                if "key" in bag:
                    place = target
                    print("Congratulations! You found the treasure.")
                    break
                print("The door is locked!")
                continue
            place = target
        elif parts[0] == "take":
            item = rooms[place]["item"]
            if item:
                bag.add(item)
                rooms[place]["item"] = None
    return place, sorted(bag)

print(play(["go north", "take", "go east", "take", "go west", "go north"]))
